//! Logging in as the user through Fidelidade's single sign-on.
//!
//! ```text
//! GET  my.fidelidade.pt/CAND_AreaCliente/AC_Documentos.aspx
//!   └─ 302 ─► autenticacao.fidelidade.pt/Autenticacao/Authorize.aspx   (OAuth2 code + PKCE)
//!        └─ the login form: NIF + password (+ "keep me signed in")
//! POST the form, "clicking" the login button
//!   └─ 302 ─► my.fidelidade.pt/canw_auth/SSOEntryPage.aspx?code=…  ─► the customer area
//! ```
//!
//! The OAuth parameters (`client_id`, PKCE challenge, `state`, `nonce`) are generated by
//! the portal and ride along in the redirects, so the crate never has to know them.
//!
//! The whole flow is plain HTTP; no CAPTCHA was present on the login page when this was
//! written. If the portal ever asks for more than NIF and password, the crate stops
//! with [`Error::InteractionRequired`] instead of guessing.

use std::fmt;

use chrono::Utc;
use scraper::Html;
use url::Url;

use crate::client::{Client, DOCUMENTS_PATH};
use crate::config::Config;
use crate::error::{Error, Result};
use crate::html::{self, selector};
use crate::session::{Http, Jar, Page};

/// NIF + the customer area's password. `Debug` never prints the password.
#[derive(Clone)]
pub struct Credentials {
    nif: String,
    password: String,
}

impl Credentials {
    /// Validates the shape the login form enforces (9-digit NIF, non-empty password) so
    /// no failed attempt is wasted on garbage.
    pub fn new(nif: impl Into<String>, password: impl Into<String>) -> Result<Self> {
        let nif = nif.into().trim().to_owned();
        let password = password.into();
        if nif.len() != 9 || !nif.bytes().all(|b| b.is_ascii_digit()) {
            return Err(Error::InvalidInput("NIF must have 9 digits".into()));
        }
        if password.is_empty() || password.chars().count() > 128 {
            return Err(Error::InvalidInput(
                "the password must have 1 to 128 characters".into(),
            ));
        }
        Ok(Self { nif, password })
    }

    /// The NIF.
    pub fn nif(&self) -> &str {
        &self.nif
    }
}

impl fmt::Debug for Credentials {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("Credentials")
            .field("nif", &self.nif)
            .field("password", &"<redacted>")
            .finish()
    }
}

/// Performs the login.
#[derive(Clone, Debug)]
pub struct Authenticator {
    config: Config,
    keep_signed_in: bool,
}

impl Default for Authenticator {
    fn default() -> Self {
        Self::new()
    }
}

impl Authenticator {
    /// Production defaults. Ticks the portal's "Manter sessão iniciada" box, which is
    /// what makes a stored session worth keeping.
    pub fn new() -> Self {
        Self::with_config(Config::default())
    }

    /// Use a custom [`Config`] (tests, proxies).
    pub fn with_config(config: Config) -> Self {
        Self {
            config,
            keep_signed_in: true,
        }
    }

    /// Whether to tick "Manter sessão iniciada" (default `true`).
    pub fn keep_signed_in(mut self, keep: bool) -> Self {
        self.keep_signed_in = keep;
        self
    }

    /// Log in with NIF + password.
    ///
    /// **Never call this in a retry loop.** On [`Error::InvalidCredentials`] stop and
    /// ask the user: repeated failures can lock the account.
    pub async fn login(&self, credentials: &Credentials) -> Result<Client> {
        let http = Http::new(self.config.clone(), Jar::new())?;

        // 1. Ask for a protected page: the portal answers with the login form.
        let start = http.get(self.config.area(DOCUMENTS_PATH)).await?;
        if self.config.is_area(&start.url) {
            return Err(Error::unexpected(
                "starting the login",
                "the portal served the customer area without asking for a login",
            ));
        }
        let doc = html::parse(&start.body);
        let login = LoginForm::parse(&doc, &start.url)?;

        // 2. "Click" the login button with the credentials filled in.
        let mut form = login.form;
        form.set(&login.username, credentials.nif());
        form.set(&login.password, &credentials.password);
        if self.keep_signed_in
            && let Some(name) = &login.keep_signed_in
        {
            form.set(name, "on");
        }
        let fields = form.post_back(&login.submit);
        let page = http
            .post_form(form.action.clone(), &fields, Some(&start.url))
            .await?;
        let page = self.follow_script_redirects(&http, page).await?;

        // 3. Classify where we ended up.
        if !self.config.is_area(&page.url) {
            return Err(self.explain_failed_login(&page));
        }
        let client = Client::new(http, credentials.nif().to_owned(), Utc::now());
        if !client.is_authenticated().await? {
            return Err(Error::unexpected(
                "finishing the login",
                format!(
                    "the portal did not accept the new session (landed on {})",
                    page.url.path()
                ),
            ));
        }
        Ok(client)
    }

    /// The login answer may be a page that redirects with script instead of a 302.
    async fn follow_script_redirects(&self, http: &Http, mut page: Page) -> Result<Page> {
        for _ in 0..5 {
            if self.config.is_area(&page.url) {
                break;
            }
            let Some(next) = html::find_js_redirect(&page.body, &page.url) else {
                break;
            };
            page = http.get(next).await?;
        }
        Ok(page)
    }

    /// Still on the login host: say why, without echoing anything personal.
    fn explain_failed_login(&self, page: &Page) -> Error {
        let doc = html::parse(&page.body);
        let still_login_form = doc
            .select(&selector("input[type=password]"))
            .next()
            .is_some();
        let message = visible_messages(&doc);
        if still_login_form {
            Error::InvalidCredentials(if message.is_empty() {
                "the login page came back without a message".to_owned()
            } else {
                message
            })
        } else {
            Error::InteractionRequired(format!(
                "the login went on to {} instead of the customer area{}",
                page.url.path(),
                if message.is_empty() {
                    String::new()
                } else {
                    format!(": {message}")
                }
            ))
        }
    }
}

/// Text of the visible feedback/validation boxes of an OutSystems page.
fn visible_messages(doc: &Html) -> String {
    let sel = selector(".Feedback_Message_Wrapper, .ValidationMessage, [role=alert]");
    let mut parts: Vec<String> = doc
        .select(&sel)
        .map(html::text_of)
        .filter(|t| !t.is_empty())
        .collect();
    parts.dedup();
    parts.join(" | ")
}

/// The login form of the single sign-on page, with the names of the controls to fill.
struct LoginForm {
    form: html::Form,
    username: String,
    password: String,
    keep_signed_in: Option<String>,
    /// Unique name of the login button, for `__EVENTTARGET`.
    submit: String,
}

impl LoginForm {
    fn parse(doc: &Html, base: &Url) -> Result<Self> {
        let unexpected = |what: &str| Error::unexpected("reading the login page", what.to_owned());
        let form =
            html::find_form(doc, base, "WebForm1").ok_or_else(|| unexpected("no login form"))?;
        let input_ending = |suffix: &str, ty: &str| {
            doc.select(&selector(&format!("input[type={ty}][name]")))
                .filter_map(|i| i.value().attr("name"))
                .find(|n| n.ends_with(suffix))
                .map(str::to_owned)
        };
        let username =
            input_ending("$wtinp_username", "text").ok_or_else(|| unexpected("no NIF field"))?;
        let password = input_ending("$wtinp_password", "password")
            .ok_or_else(|| unexpected("no password field"))?;
        let keep_signed_in = input_ending("$wtCheckbox_IsPersistentLogin", "checkbox");
        let submit = doc
            .select(&selector("a[id$=wtlnk_Login]"))
            .next()
            .and_then(|a| a.value().attr("onclick"))
            .and_then(html::os_ajax_target)
            .ok_or_else(|| unexpected("no login button"))?;
        Ok(Self {
            form,
            username,
            password,
            keep_signed_in,
            submit,
        })
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn credentials_validate_shape() {
        assert!(Credentials::new("123456789", "x").is_ok());
        assert!(Credentials::new("12345678", "x").is_err());
        assert!(Credentials::new("12345678a", "x").is_err());
        assert!(Credentials::new("123456789", "").is_err());
        let debug = format!("{:?}", Credentials::new("123456789", "hunter2").unwrap());
        assert!(!debug.contains("hunter2"));
    }
}
